// Check if a symbol is in NSE F&O
export function isFnoStock(symbol: string): boolean {
  const clean = symbol.toUpperCase().replace(/\.NS$|\.BO$/i, '').trim();
  return Boolean(NSE_FNO_REGISTRY[clean] || NSE_FNO_REGISTRY[clean.replace(/\s+/g, '')]);
}

// Get clean symbol
export function getCleanSymbol(symbol: string): string {
  return symbol.toUpperCase().replace(/\.NS$|\.BO$/i, '').trim();
}

// Normal Cumulative Distribution Function N(x)
export function normalCdf(x: number): number {
  const a1 = 0.254829592;
  const a2 = -0.284496736;
  const a3 = 1.421413741;
  const a4 = -1.453152027;
  const a5 = 1.061405429;
  const p = 0.3275911;
  const sign = x < 0 ? -1 : 1;
  const absX = Math.abs(x) / Math.sqrt(2.0);
  const t = 1.0 / (1.0 + p * absX);
  const erf = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-absX * absX);
  return 0.5 * (1.0 + sign * erf);
}

// Normal Probability Density Function N'(x)
export function normalPdf(x: number): number {
  return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
}

// Standard NSE F&O Tick Size is ₹0.05
export function roundToNseTick(val: number): number {
  return Math.round(Math.max(0.05, val) * 20) / 20;
}

// Black-Scholes European option valuation (continuous time, no dividends).
export function computeBlackScholes(
  s: number, // Spot Price
  k: number, // Strike Price
  tDays: number, // Days to Expiry
  r: number = 0.065, // RBI Repo Rate ~6.5%
  sigma: number = 0.16 // Implied Volatility
) {
  if (![s, k, tDays, r, sigma].every(Number.isFinite) || s <= 0 || k <= 0 || sigma < 0) {
    throw new RangeError('Black-Scholes requires positive spot/strike, non-negative volatility, and finite inputs.');
  }
  if (tDays <= 0) {
    const callPrice = Math.max(0, s - k);
    const putPrice = Math.max(0, k - s);
    const callDelta = s > k ? 1 : s < k ? 0 : 0.5;
    return {
      callPrice: roundToNseTick(callPrice),
      putPrice: roundToNseTick(putPrice),
      callDelta,
      putDelta: callDelta - 1,
      gamma: 0,
      callTheta: 0,
      putTheta: 0,
      vega: 0,
      callRho: 0,
      putRho: 0,
      d1: 0,
      d2: 0
    };
  }
  const t = tDays / 365.0;
  const safeSigma = Math.max(1e-8, sigma);
  const sqrtT = Math.sqrt(t);

  const d1 = (Math.log(s / k) + (r + 0.5 * safeSigma * safeSigma) * t) / (safeSigma * sqrtT);
  const d2 = d1 - safeSigma * sqrtT;

  const nd1 = normalCdf(d1);
  const nd2 = normalCdf(d2);
  const n_minus_d1 = normalCdf(-d1);
  const n_minus_d2 = normalCdf(-d2);
  const pdf_d1 = normalPdf(d1);
  const discountFactor = Math.exp(-r * t);

  // Exact Black-Scholes Theoretical Prices with ₹0.05 NSE Tick Precision
  const callPrice = Math.max(0.05, s * nd1 - k * discountFactor * nd2);
  const putPrice = Math.max(0.05, k * discountFactor * n_minus_d2 - s * n_minus_d1);

  // Greeks
  const callDelta = Math.round(nd1 * 1000) / 1000;
  const putDelta = Math.round((callDelta - 1.0) * 1000) / 1000; // Strictly guarantees Call Delta - Put Delta = 1.000
  const gamma = Math.round((pdf_d1 / (s * safeSigma * sqrtT)) * 10000) / 10000;

  // Theta in ₹ decay per day
  const callThetaAnnual = -(s * pdf_d1 * safeSigma) / (2 * sqrtT) - r * k * discountFactor * nd2;
  const putThetaAnnual = -(s * pdf_d1 * safeSigma) / (2 * sqrtT) + r * k * discountFactor * n_minus_d2;
  const callThetaDay = Math.round((callThetaAnnual / 365.0) * 10000) / 10000;
  const putThetaDay = Math.round((putThetaAnnual / 365.0) * 10000) / 10000;

  // Vega (price sensitivity per 1% change in IV)
  const vega = Math.round(s * sqrtT * pdf_d1 * 0.01 * 10000) / 10000;

  // Rho (sensitivity per 1% change in RBI benchmark rate)
  const callRho = Math.round((k * t * discountFactor * nd2 * 0.01) * 100) / 100;
  const putRho = Math.round((-k * t * discountFactor * n_minus_d2 * 0.01) * 100) / 100;

  return {
    callPrice: roundToNseTick(callPrice),
    putPrice: roundToNseTick(putPrice),
    callDelta,
    putDelta,
    gamma,
    callTheta: callThetaDay,
    putTheta: putThetaDay,
    vega,
    callRho,
    putRho,
    d1,
    d2
  };
}

// Bisection Implied Volatility Solver to reverse-engineer exact market IV from traded settlement price
export function solveImpliedVolFromPrice(
  s: number,
  k: number,
  tDays: number,
  targetPrice: number,
  isCall: boolean,
  r: number = 0.065
): number {
  let low = 0.02;
  let high = 2.5;
  for (let iter = 0; iter < 24; iter++) {
    const mid = (low + high) / 2;
    const bs = computeBlackScholes(s, k, tDays, r, mid);
    const p = isCall ? bs.callPrice : bs.putPrice;
    if (p < targetPrice) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return Math.round(((low + high) / 2) * 1000) / 1000;
}

