// Explicit route for WebAssembly binaries with strict application/wasm Content-Type
app.get('/sql-wasm.wasm', (req, res) => {
  const possiblePaths = [
    path.join(process.cwd(), 'public', 'sql-wasm.wasm'),
    path.join(process.cwd(), 'dist', 'sql-wasm.wasm'),
    path.join(process.cwd(), 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm')
  ];
  for (const p of possiblePaths) {
    if (fs.existsSync(p)) {
      res.setHeader('Content-Type', 'application/wasm');
      res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
      return res.sendFile(p);
    }
  }
  return res.status(404).type('text/plain').send('sql-wasm.wasm not found');
});

