// Market Data Provider Fetch Endpoint (Indian Stocks NSE/BSE & MCX Commodities)
app.get('/api/market/fetch', async (req, res) => {
  try {
    const provider = String(req.query.provider || 'yahoo');
    const rawSymbol = String(req.query.symbol || 'RELIANCE').trim().toUpperCase();
    const range = String(req.query.range || '6mo');
    const interval = String(req.query.interval || '1d');
    const usdInr = await getUsdInrRate();

    if (provider === 'binance') {
      let binanceSymbol = rawSymbol.replace(/[-/_]/g, '');
      if (!binanceSymbol.endsWith('USDT') && !binanceSymbol.endsWith('BUSD') && !binanceSymbol.endsWith('BTC')) {
        binanceSymbol += 'USDT';
      }
      const binInterval = interval === '1h' ? '1h' : interval === '1wk' ? '1w' : '1d';
      const bRes = await fetch(`https://api.binance.com/api/v3/klines?symbol=${binanceSymbol}&interval=${binInterval}&limit=150`);
      if (!bRes.ok) {
        return res.status(bRes.status).json({ error: `Binance error: ${bRes.statusText}` });
      }
      const rawKlines = await bRes.json();
      // Convert all USDT/USD crypto prices accurately to Indian Rupees (₹)
      const points = rawKlines.map((k: any[]) => {
        const d = new Date(k[0]);
        const closeUsd = parseFloat(k[4]);
        const openUsd = parseFloat(k[1]);
        const highUsd = parseFloat(k[2]);
        const lowUsd = parseFloat(k[3]);
        return {
          timestamp: binInterval === '1h' ? d.toISOString().slice(0, 16).replace('T', ' ') : d.toISOString().split('T')[0],
          value: Math.round(closeUsd * usdInr * 100) / 100,
          open: Math.round(openUsd * usdInr * 100) / 100,
          high: Math.round(highUsd * usdInr * 100) / 100,
          low: Math.round(lowUsd * usdInr * 100) / 100,
          volume: Math.round(parseFloat(k[5]) * 10) / 10
        };
      });

      return res.json({
        symbol: binanceSymbol,
        name: `${binanceSymbol} (in Indian Rupees ₹)`,
        currency: 'INR',
        unit: 'INR (₹)',
        provider: 'binance',
        sourceState: 'LIVE',
        isLive: true,
        fetchedAt: new Date().toISOString(),
        data: points
      });
    }

    // Comprehensive ADR to NSE mapping
    const ADR_TO_NSE_MAP: Record<string, string> = {
      'INFY': 'INFY.NS',
      'IBN': 'ICICIBANK.NS',
      'HDB': 'HDFCBANK.NS',
      'WIT': 'WIPRO.NS',
      'VEDL': 'VEDL.NS',
      'TTM': 'TATAMOTORS.NS',
      'MM': 'M&M.NS',
      'RDY': 'DRREDDY.NS'
    };

    // Helper: search Yahoo quotes with strict preference for Indian Exchanges (.NS / .BO)
    const searchYahooQuote = async (query: string): Promise<{ symbol: string; name: string } | null> => {
      try {
        const sUrl = `https://query2.finance.yahoo.com/v1/finance/search?q=${encodeURIComponent(query)}&quotesCount=15&newsCount=0`;
        const sRes = await fetch(sUrl, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
          }
        });
        if (!sRes.ok) return null;
        const sData = await sRes.json();
        const quotes: any[] = sData?.quotes || [];
        if (quotes.length === 0) return null;

        // 1. Prefer Indian Exchange quotes (.NS, .BO, exchange NSI, NSE, BSE, BOM)
        const indian = quotes.find(q =>
          q.symbol?.endsWith('.NS') ||
          q.symbol?.endsWith('.BO') ||
          q.exchange === 'NSI' ||
          q.exchange === 'NSE' ||
          q.exchange === 'BSE' ||
          q.exchange === 'BOM'
        );
        if (indian) {
          return {
            symbol: indian.symbol,
            name: indian.longname || indian.shortname || indian.symbol
          };
        }

        // 2. Check if any quote is an ADR mapping to NSE
        for (const q of quotes) {
          const symUpper = (q.symbol || '').toUpperCase();
          if (ADR_TO_NSE_MAP[symUpper]) {
            return {
              symbol: ADR_TO_NSE_MAP[symUpper],
              name: q.longname || q.shortname || symUpper
            };
          }
        }

        // 3. Next prefer general equities or commodities
        const general = quotes.find(q => 
          q.quoteType === 'EQUITY' || 
          q.quoteType === 'COMMODITY' || 
          q.quoteType === 'FUTURE' || 
          q.quoteType === 'INDEX'
        ) || quotes[0];

        if (general) {
          return {
            symbol: general.symbol,
            name: general.longname || general.shortname || general.symbol
          };
        }
        return null;
      } catch {
        return null;
      }
    };

    // Helper: fetch chart data from Yahoo with interval-range auto-alignment
    const fetchYahooChart = async (sym: string) => {
      let effectiveRange = range;
      if (interval === '15m' || interval === '5m' || interval === '1m' || interval === '30m') {
        if (range === '6mo' || range === '1y' || range === '2y' || range === '5y' || range === 'max') {
          effectiveRange = '1mo'; // Max supported range for intraday 15m on Yahoo is 1mo/60d
        }
      } else if (interval === '1h') {
        if (range === '2y' || range === '5y' || range === 'max') {
          effectiveRange = '730d';
        }
      }
      const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?range=${effectiveRange}&interval=${interval}`;
      const res = await fetch(url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        }
      });
      return res;
    };

    let targetSymbol = rawSymbol;
    let resolvedFormalName: string | undefined;
    let yRes: Response | null = null;

    if (INDIAN_SYMBOL_MAP[rawSymbol]) {
      targetSymbol = INDIAN_SYMBOL_MAP[rawSymbol];
      yRes = await fetchYahooChart(targetSymbol);
    } else if (rawSymbol.endsWith('.NS') || rawSymbol.endsWith('.BO') || rawSymbol.startsWith('^') || rawSymbol.includes('=')) {
      targetSymbol = rawSymbol;
      yRes = await fetchYahooChart(targetSymbol);
    } else {
      const cleanUpper = rawSymbol.replace(/[\s\-_]/g, '');
      if (INDIAN_SYMBOL_MAP[cleanUpper]) {
        targetSymbol = INDIAN_SYMBOL_MAP[cleanUpper];
        yRes = await fetchYahooChart(targetSymbol);
      } else {
        // Direct test: Try appending .NS (National Stock Exchange) first
        const nsCandidate = `${cleanUpper}.NS`;
        const testNsRes = await fetchYahooChart(nsCandidate);
        if (testNsRes.ok) {
          targetSymbol = nsCandidate;
          yRes = testNsRes;
        } else {
          // Direct test: Try appending .BO (Bombay Stock Exchange)
          const boCandidate = `${cleanUpper}.BO`;
          const testBoRes = await fetchYahooChart(boCandidate);
          if (testBoRes.ok) {
            targetSymbol = boCandidate;
            yRes = testBoRes;
          } else {
            // Search Yahoo Quote
            const searchHit = await searchYahooQuote(rawSymbol);
            if (searchHit) {
              targetSymbol = searchHit.symbol;
              resolvedFormalName = searchHit.name;
              yRes = await fetchYahooChart(targetSymbol);
            }
          }
        }
      }
    }

    if (!yRes || !yRes.ok) {
      // Fallback search with spaced company query
      const spacedQuery = rawSymbol.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/(MOTORS|BANK|STEEL|PHARMA|POWER|TECH|AUTO|FINANCE)/g, ' $1').trim();
      const searchHit = await searchYahooQuote(spacedQuery !== rawSymbol ? spacedQuery : rawSymbol);
      if (searchHit && searchHit.symbol !== targetSymbol) {
        targetSymbol = searchHit.symbol;
        resolvedFormalName = searchHit.name;
        yRes = await fetchYahooChart(targetSymbol);
      }
    }

    if (!yRes || !yRes.ok) {
      return res.status(yRes?.status || 404).json({ error: `Market data provider responded with status ${yRes?.status || 404} for symbol "${rawSymbol}"` });
    }

    const json = await yRes.json();
    const result = json?.chart?.result?.[0];
    if (!result) {
      return res.status(404).json({ error: `No market chart data found for "${rawSymbol}"` });
    }

    const timestamps = result.timestamp || [];
    const quote = result.indicators?.quote?.[0] || {};
    const opens = quote.open || [];
    const highs = quote.high || [];
    const lows = quote.low || [];
    const closes = quote.close || [];
    const volumes = quote.volume || [];

    // Calculate accurate conversion multiplier to Indian Rupees (₹ / INR)
    const isIndianNative = targetSymbol.endsWith('.NS') || targetSymbol.endsWith('.BO') || targetSymbol.startsWith('^NSE') || targetSymbol.startsWith('^BSE');
    let multiplier = 1.0;
    let customCommodityName: string | undefined;

    if (targetSymbol === 'GC=F') {
      // COMEX Gold USD/oz -> MCX Gold ₹ per 10 grams (1 oz = 31.1034768g, with customs ~1.08)
      multiplier = (1 / 31.1034768) * 10 * usdInr * 1.08;
      customCommodityName = 'MCX Gold Futures (₹ / 10g)';
    } else if (targetSymbol === 'SI=F') {
      // COMEX Silver USD/oz -> MCX Silver ₹ per 1 kg (1000g)
      multiplier = (1 / 31.1034768) * 1000 * usdInr * 1.08;
      customCommodityName = 'MCX Silver Futures (₹ / kg)';
    } else if (targetSymbol === 'CL=F') {
      // COMEX Crude Oil USD/barrel -> MCX Crude Oil ₹ per barrel
      multiplier = usdInr;
      customCommodityName = 'MCX Crude Oil (₹ / bbl)';
    } else if (targetSymbol === 'NG=F') {
      // COMEX Natural Gas USD/mmBtu -> MCX Natural Gas ₹ per mmBtu
      multiplier = usdInr;
      customCommodityName = 'MCX Natural Gas (₹ / mmBtu)';
    } else if (targetSymbol === 'HG=F') {
      // COMEX Copper USD/lb -> MCX Copper ₹ per kg (1 kg = 2.20462 lbs)
      multiplier = 2.20462 * usdInr;
      customCommodityName = 'MCX Copper (₹ / kg)';
    } else if (!isIndianNative && result.meta?.currency && result.meta.currency !== 'INR') {
      // Foreign stock or ETF denominated in USD or foreign currency
      multiplier = usdInr;
    }

    const data: TimeSeriesPoint[] = [];
    for (let i = 0; i < timestamps.length; i++) {
      const c = closes[i];
      if (c !== null && c !== undefined && !isNaN(c)) {
        const d = new Date(timestamps[i] * 1000);
        data.push({
          timestamp: interval.includes('h') || interval.includes('m') 
            ? d.toISOString().slice(0, 16).replace('T', ' ') 
            : d.toISOString().split('T')[0],
          value: Math.round(c * multiplier * 100) / 100,
          open: opens[i] ? Math.round(opens[i] * multiplier * 100) / 100 : undefined,
          high: highs[i] ? Math.round(highs[i] * multiplier * 100) / 100 : undefined,
          low: lows[i] ? Math.round(lows[i] * multiplier * 100) / 100 : undefined,
          volume: volumes[i] || 0
        });
      }
    }

    const formalName = customCommodityName || resolvedFormalName || result.meta?.shortName || result.meta?.longName || `${rawSymbol} Market Chart`;

    const lastClosePrice = data.length > 0 ? data[data.length - 1].value : undefined;
    const prevClosePrice = data.length > 1 ? data[data.length - 2].value : lastClosePrice;
    const priceChange = lastClosePrice && prevClosePrice ? Math.round((lastClosePrice - prevClosePrice) * 100) / 100 : 0;
    const priceChangePct = prevClosePrice && prevClosePrice > 0 ? Math.round((priceChange / prevClosePrice) * 10000) / 100 : 0;

    return res.json({
      symbol: result.meta?.symbol || targetSymbol,
      name: formalName,
      currency: 'INR',
      unit: 'INR (₹)',
      provider: 'yahoo',
      sourceState: 'LIVE',
      isLive: true,
      fetchedAt: new Date().toISOString(),
      lastClosePrice,
      previousClose: prevClosePrice,
      priceChange,
      priceChangePercent: priceChangePct,
      data
    });
  } catch (err: any) {
    console.error('Market provider fetch error:', err);
    return res.status(500).json({ error: err.message || 'Failed to fetch provider data' });
  }
});

// Helper for Black-Scholes Greeks calculation
function normalCdf(x: number): number {
  const a1 = 0.254829592;
  const a2 = -0.284496736;
  const a3 = 1.421413741;
  const a4 = -1.453152027;
  const a5 = 1.061405429;
  const p = 0.3275911;
  const sign = x < 0 ? -1 : 1;
  const absX = Math.abs(x) / Math.sqrt(2.0);
  const t = 1.0 / (1.0 + p * absX);
  const erf = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-absX * absX);
  return 0.5 * (1.0 + sign * erf);
}

function calculateOptionGreeks(s: number, k: number, tDays: number, r: number = 0.065, sigma: number = 0.16) {
  const t = Math.max(tDays, 0.5) / 365;
  const safeSigma = Math.max(0.01, sigma);
  const d1 = (Math.log(s / k) + (r + (safeSigma * safeSigma) / 2) * t) / (safeSigma * Math.sqrt(t));
  const d2 = d1 - safeSigma * Math.sqrt(t);

  const callDelta = Math.round(normalCdf(d1) * 100) / 100;
  const putDelta = Math.round((callDelta - 1) * 100) / 100;
  const gamma = Math.round((Math.exp(-0.5 * d1 * d1) / (s * safeSigma * Math.sqrt(2 * Math.PI * t))) * 10000) / 10000;
  const theta = Math.round((-(s * safeSigma * Math.exp(-0.5 * d1 * d1)) / (2 * Math.sqrt(2 * Math.PI * t) * 365)) * 100) / 100;

  return {
    callDelta,
    putDelta,
    gamma,
    theta: Math.abs(theta)
  };
}

